#include <stdio.h>

int main() {
    int age;
    printf("Enter your age: ");
    if (scanf("%d", &age) != 1) {          // & required; check the return value
        printf("Invalid input\n");
        return 1;
    }
    printf("You are %d years old\n", age);

    int c;
    while ((c = getchar()) != '\n' && c != EOF) {
        putchar(c);                          // echo each character
    }
    return 0;
}
